samples.raw_completion:
// Large reservoir of water, flow rate controlled by sensors at 5-inch
// intervals. Flow rate is determined by the water level and the level
// previous to the last sensor change, as described in the problem
// description.
module TopModule(
  input  clk,
  input  reset,
  input  [2:0] s,
  output fr2,
  output fr1,
  output fr0,
  output dfr
);
  reg [2:0] level;
  reg [2:0] last_level;
  reg [1:0] state;
  reg [1:0] next_state;
  wire [1:0] next_level = level + 1'b1;
  wire [1:0] last_next_level = last_level + 1'b1;
  wire fr2_next = (state == 2'b00) ? 1'b0 : (state == 2'b01) ? 1'b0 : (state == 2'b10) ? 1'b1 : 1'b0;
  wire fr1_next = (state == 2'b00) ? 1'b0 : (state == 2'b01) ? 1'b1 : 1'b0;
  wire fr0_next = (state == 2'b00) ? 1'b1 : 1'b0;
  wire dfr_next = (state == 2'b01) ? 1'b1 : (state == 2'b10) ? 1'b1 : 1'b0;
  always @(*) begin
    if (s[2]) next_state = 2'b00;
    else if (s[1]) next_state = 2'b01;
    else if (s[0]) next_state = 2'b10;
    else next_state = 2'b11;
  end
  always @(posedge clk) begin
    if (reset) begin
      level <= 3'b000;
      last_level <= 3'b111;
      state <= 2'b11;
    end else begin
      level <= next_level;
      last_level <= level;
      state <= next_state;
    end
  end
  assign fr2 = fr2_next;
  assign fr1 = fr1_next;
  assign fr0 = fr0_next;
  assign dfr = dfr_next;
endmodule

