// Large reservoir, flow rate determined by 3 sensors and two independent
// flow rate inputs, plus a reset to go to a high flow state.
module TopModule(
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);
    reg [2:0] level_d1, level_d2;
    reg [2:0] level;
    always @(posedge clk) begin
        if (reset) begin
            level <= 3'b111;
            level_d1 <= 3'b111;
            level_d2 <= 3'b111;
            {fr2, fr1, fr0, dfr} <= 4'b1111;
        end else begin
            level <= s;
            level_d1 <= level;
            level_d2 <= level_d1;
            case ({level_d2, level_d1, level})
                9'b0001111: begin fr2 <= 1; fr1 <= 1; fr0 <= 1; dfr <= 0; end
                9'b0011111: begin fr2 <= 1; fr1 <= 1; fr0 <= 0; dfr <= 0; end
                9'b0111111: begin fr2 <= 1; fr1 <= 0; fr0 <= 0; dfr <= 0; end
                default: begin
                    fr2 <= 0;
                    fr1 <= 0;
                    fr0 <= 0;
                    dfr <= (level_d1 < level);
                end
            endcase
        end
    end
endmodule

