// Large reservoir of water, flow rate determined by sensors and the level
// of the water previous to the last sensor change. The flow rate is
// determined by two factors: the water level and the level previous to
// the last sensor change. Each water level has a nominal flow rate
// associated with it.
module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);
    reg [2:0] level;
    reg [2:0] last_level;
    reg [2:0] last_last_level;
    reg [1:0] state;
    reg [1:0] next_state;
    reg [2:0] nominal_rate;
    reg [2:0] next_nominal_rate;
    reg open_supp_valve;
    reg open_nom_valve;
    wire [2:0] fr;
    wire [2:0] next_fr;
    assign fr = {open_nom_valve, open_supp_valve} & nominal_rate;
    assign {fr2, fr1, fr0} = fr;
    assign dfr = state[0] ^ state[1];
    always @* begin
        case (state)
            2'b00: next_state = 2'b01;
            2'b01: next_state = {level[2], ~level[2]} & {2{level[1]}} + 2'b10;
            2'b10: next_state = {level[2], ~level[2]} & {2{level[0]}} + 2'b11;
            2'b11: next_state = 2'b00;
        endcase
    end
    always @* begin
        case (state)
            2'b00: next_nominal_rate = 3'b001;
            2'b01: next_nominal_rate = level[0] ? 3'b001 : 3'b010;
            2'b10: next_nominal_rate = level[0] ? 3'b001 : (level[1] ? 3'b010 : 3'b100);
            2'b11: next_nominal_rate = 3'b100;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            level <= 3'b000;
            last_level <= 3'b000;
            last_last_level <= 3'b000;
            state <= 2'b00;
            nominal_rate <= 3'b001;
            open_supp_valve <= 1'b1;
            open_nom_valve <= 1'b1;
        end else begin
            level <= s;
            last_level <= level;
            last_last_level <= last_level;
            state <= next_state;
            nominal_rate <= next_nominal_rate;
            open_supp_valve <= state[0] ^ state[1];
            open_nom_valve <= ~state[0] & ~state[1];
        end
    end
endmodule

