// Large reservior of water, flow rate controlled by three sensors and two
// independent factors: the water level and the level previous to the last
// sensor change.
module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);
    reg [2:0] level;
    reg [2:0] last_level;
    always @(posedge clk) begin
        if (reset) begin
            level <= 3'b111;
            last_level <= 3'b000;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            last_level <= level;
            case (s)
                3'b000: level <= 3'b000;
                3'b001: level <= 3'b001;
                3'b010: level <= 3'b010;
                3'b011: level <= 3'b011;
                3'b100: level <= 3'b100;
                default: level <= 3'b111;
            endcase
            case ({last_level < level, level})
                5'b0_0000: begin fr2 <= 1'b1; fr1 <= 1'b1; fr0 <= 1'b1; dfr <= 1'b1; end
                5'b0_0001: begin fr2 <= 1'b0; fr1 <= 1'b1; fr0 <= 1'b1; dfr <= 1'b1; end
                5'b0_0010: begin fr2 <= 1'b0; fr1 <= 1'b1; fr0 <= 1'b1; dfr <= 1'b1; end
                5'b0_0011: begin fr2 <= 1'b0; fr1 <= 1'b0; fr0 <= 1'b1; dfr <= 1'b1; end
                5'b0_0100: begin fr2 <= 1'b0; fr1 <= 1'b0; fr0 <= 1'b1; dfr <= 1'b0; end
                5'b0_0101: begin fr2 <= 1'b0; fr1 <= 1'b0; fr0 <= 1'b1; dfr <= 1'b0; end
                5'b0_0110: begin fr2 <= 1'b0; fr1 <= 1'b0; fr0 <= 1'b0; dfr <= 1'b0; end
                5'b0_0111: begin fr2 <= 1'b0; fr1 <= 1'b0; fr0 <= 1'b0; dfr <= 1'b0; end
                5'b1_1110: begin fr2 <= 1'b0; fr1 <= 1'b0; fr0 <= 1'b0; dfr <= 1'b1; end
                default:  begin fr2 <= 1'b0; fr1 <= 1'b0; fr0 <= 1'b0; dfr <= 1'b1; end
            endcase
        end
    end
endmodule

